# -*- coding: utf-8 -*-
"""Butir pencegahan perkawinan bagian C: musyawarah dan upaya damai, serta pengetahuan calon mempelai yang menghadap. Agen W2b-B."""
from isi_pencegahan import S

# ------------------------------------------------------------------ musyawarah dan upaya damai (urutan 141-144)
S(id='u-musyawarah', pokok='pp-pc-upaya-damai', urut_abs=141, tingkat='pilihan', fam='hadir',
  teks='Apakah keluarga pernah bermusyawarah dengan kedua calon mempelai sebelum perkara ini diajukan dan siapa saja yang hadir ?',
  varian=['Apakah sebelum perkara ini diajukan sudah ada pertemuan keluarga dengan para calon mempelai dan siapa yang hadir pada pertemuan itu ?'],
  hal='musyawarah keluarga dengan kedua calon mempelai sebelum perkara diajukan', m='musyawarah keluarga dengan kedua calon mempelai sebelum perkara diajukan',
  K=(['keluarga sudah berkumpul dan bermusyawarah dengan kedua calon mempelai dan keluarganya sebelum perkara ini diajukan',
      'sebelum perkara ini diajukan pihak keluarga telah mengadakan pertemuan dengan para calon mempelai untuk membicarakan keberatan itu'],
     ['pertemuan keluarga dengan kedua calon mempelai sudah diadakan dan dihadiri beberapa kerabat kedua belah pihak',
      'dalam musyawarah keluarga yang diadakan sebelum perkara ini keberatan #0046# dibicarakan di depan para kerabat']),
  M=(['#0046# berkata di hadapan keluarga bahwa ia berkeberatan atas perkawinan itu',
      '#0046# menyatakan keberatannya secara langsung dalam pertemuan keluarga'],
     ['dalam pertemuan keluarga #0046# mengatakan bahwa ia menolak perkawinan itu',
      'di depan para kerabat #0046# menyatakan bahwa perkawinan itu ia tolak']),
  P=(['keluarga sudah berkumpul dan bermusyawarah dengan kedua calon mempelai', 'pihak keluarga telah mengadakan pertemuan dengan para calon mempelai'],
     ['pertemuan keluarga dengan kedua calon mempelai sudah diadakan', 'musyawarah keluarga itu dihadiri beberapa kerabat kedua belah pihak']),
  A=['musyawarah keluarga dengan kedua calon mempelai diadakan satu kali', 'pertemuan keluarga dengan para calon mempelai hanya terlaksana sekali'],
  B=['musyawarah keluarga dengan kedua calon mempelai diadakan berkali-kali', 'pertemuan keluarga dengan para calon mempelai terlaksana berulang kali'],
  beda_pada='jumlah', beda_maksud='versi A: musyawarah keluarga satu kali; versi B: berkali-kali - berselisih pada JUMLAH pertemuan',
  peran={'keluarga-pemohon': (['sebagai keluarga #0046# saya ikut hadir dalam musyawarah yang diadakan dengan para calon mempelai sebelum perkara ini diajukan',
                               'saya yang masih sekeluarga dengan #0046# turut duduk dalam pertemuan dengan kedua calon mempelai sebelum perkara ini',
                               'dalam pertemuan keluarga sebelum perkara ini diajukan saya hadir sebagai kerabat #0046# dan menyaksikan pembicaraan itu',
                               'saya kerabat #0046# dan saya sendiri ikut bermusyawarah dengan para calon mempelai pada waktu itu'],
                              ['karena saya famili #0046# saya berada di tengah pertemuan dengan para calon mempelai sebelum perkara ini diajukan',
                               'musyawarah dengan kedua calon mempelai itu saya ikuti langsung sebagai keluarga #0046#',
                               'sebagai bagian dari keluarga #0046# saya ada di tempat ketika pertemuan dengan para calon mempelai berlangsung',
                               'saya hadir dalam pembicaraan keluarga #0046# dengan kedua calon mempelai sebelum perkara ini dibawa ke pengadilan']),
        'keluarga-calon-mempelai': (['sebagai keluarga calon mempelai saya hadir ketika keluarga #0046# datang bermusyawarah sebelum perkara ini diajukan',
                                     'saya masih keluarga calon mempelai dan saya menerima kedatangan #0046# dalam musyawarah sebelum perkara ini',
                                     'dalam pertemuan sebelum perkara ini diajukan saya hadir sebagai kerabat calon mempelai dan menyaksikan pembicaraannya',
                                     'saya kerabat calon mempelai dan saya sendiri ikut duduk dalam musyawarah dengan #0046# waktu itu'],
                                    ['karena saya famili calon mempelai saya berada di tengah pertemuan dengan #0046# sebelum perkara ini diajukan',
                                     'musyawarah dengan #0046# itu saya ikuti langsung sebagai keluarga calon mempelai',
                                     'sebagai bagian dari keluarga calon mempelai saya ada di tempat ketika #0046# datang membicarakan keberatannya',
                                     'saya hadir dalam pembicaraan keluarga calon mempelai dengan #0046# sebelum perkara ini dibawa ke pengadilan'])})

S(id='u-keberatan-lisan', pokok='pp-pc-upaya-damai', urut_abs=142, tingkat='inti', fam='hadir',
  teks='Kapan dan kepada siapa #0046# menyampaikan keberatannya atas perkawinan itu dan apakah saksi melihat atau mendengarnya sendiri ?',
  varian=['Apakah saksi melihat atau mendengar sendiri #0046# menyampaikan keberatan atas perkawinan itu kepada kedua calon mempelai ?'],
  hal='penyampaian keberatan #0046# kepada kedua calon mempelai', m='penyampaian keberatan #0046# kepada kedua calon mempelai',
  K=(['#0046# menyampaikan keberatannya atas perkawinan itu secara langsung kepada para calon mempelai',
      'kepada para calon mempelai #0046# menyatakan keberatannya atas rencana perkawinan itu dengan lisan'],
     ['keberatan #0046# atas perkawinan itu sudah ia sampaikan sendiri kepada kedua calon mempelai',
      '#0046# mengatakan kepada kedua calon mempelai bahwa ia berkeberatan atas rencana perkawinan mereka']),
  M='K',
  P=(['#0046# menyampaikan keberatannya kepada para calon mempelai', 'kepada para calon mempelai #0046# menyatakan keberatannya'],
     ['keberatan #0046# sudah ia sampaikan sendiri kepada kedua calon mempelai', '#0046# mengatakan kepada kedua calon mempelai bahwa ia berkeberatan']),
  A=['#0046# menyampaikan keberatannya di rumah calon mempelai', 'keberatan #0046# dinyatakannya di kediaman calon mempelai'],
  B=['#0046# menyampaikan keberatannya melalui surat tertulis', 'keberatan #0046# dikirimkannya dalam bentuk surat'],
  beda_pada='peristiwa', beda_maksud='versi A: keberatan disampaikan langsung di rumah calon mempelai; versi B: disampaikan melalui surat - berselisih pada PERISTIWA/cara penyampaian')

S(id='u-tanggapan', pokok='pp-pc-upaya-damai', urut_abs=143, tingkat='pilihan', fam='hadir',
  teks='Bagaimana tanggapan para calon mempelai dan keluarganya terhadap keberatan #0046# itu ?',
  varian=['Apa jawaban kedua calon mempelai dan keluarganya ketika keberatan #0046# disampaikan kepada mereka ?'],
  hal='tanggapan para calon mempelai atas keberatan #0046#', m='tanggapan para calon mempelai dan keluarganya atas keberatan #0046#',
  K=(['para calon mempelai dan keluarganya tetap hendak melanjutkan perkawinan itu walaupun keberatan #0046# sudah disampaikan',
      'meskipun sudah mengetahui keberatan #0046# para calon mempelai berkeras melangsungkan perkawinan mereka'],
     ['keberatan #0046# ditanggapi oleh para calon mempelai dengan terus melanjutkan persiapan perkawinan',
      'keluarga para calon mempelai menanggapi keberatan #0046# dengan terus berjalan menuju akad nikah']),
  M=(['salah seorang calon mempelai berkata bahwa perkawinan itu tetap akan dilangsungkan',
      'keluarga calon mempelai mengatakan kepada #0046# bahwa akad nikah tetap akan dilaksanakan'],
     ['calon mempelai menyatakan di hadapan keluarga bahwa ia tetap hendak menikah',
      'keluarga calon mempelai berkata kepada #0046# bahwa rencana perkawinan itu terus dijalankan']),
  P=(['para calon mempelai dan keluarganya tetap hendak melanjutkan perkawinan itu', 'para calon mempelai berkeras melangsungkan perkawinan mereka'],
     ['para calon mempelai terus melanjutkan persiapan perkawinan', 'keluarga para calon mempelai terus berjalan menuju akad nikah']),
  A=['para calon mempelai tetap melanjutkan perkawinan itu', 'kedua calon mempelai berkeras melangsungkan akad nikah'],
  B=['para calon mempelai bersedia menunda perkawinan itu', 'kedua calon mempelai menyatakan akan menunda akad nikah'],
  beda_pada='peristiwa', beda_maksud='versi A: calon mempelai tetap melanjutkan perkawinan; versi B: bersedia menunda - berselisih pada PERISTIWA/sikap calon mempelai')

S(id='u-tokoh', pokok='pp-pc-upaya-damai', urut_abs=144, tingkat='tambahan',
  teks='Apakah tokoh agama, tokoh masyarakat atau perangkat desa pernah diminta menengahi persoalan perkawinan ini ?',
  varian=['Apakah pernah ada tokoh agama atau perangkat desa yang diminta ikut menyelesaikan keberatan atas perkawinan ini ?'],
  hal='peran tokoh agama atau perangkat desa dalam menengahi persoalan perkawinan', m='peran tokoh agama atau perangkat desa dalam menengahi persoalan perkawinan', fam='tahu',
  K=(['tokoh agama atau perangkat desa setempat sudah diminta menengahi persoalan perkawinan itu',
      'persoalan perkawinan itu sudah dibawa kepada tokoh masyarakat setempat untuk dimusyawarahkan'],
     ['perangkat desa dan tokoh agama setempat telah ikut menengahi keberatan #0046# atas perkawinan itu',
      'keberatan #0046# atas perkawinan itu telah dibicarakan melalui tokoh masyarakat yang dituakan di sana']),
  P=(['tokoh agama atau perangkat desa setempat sudah diminta menengahi', 'persoalan perkawinan itu sudah dibawa kepada tokoh masyarakat setempat'],
     ['perangkat desa dan tokoh agama setempat telah ikut menengahi', 'keberatan #0046# telah dibicarakan melalui tokoh masyarakat']),
  A=['tokoh agama setempat sudah diminta menengahi persoalan itu', 'perangkat desa sudah ikut menengahi persoalan perkawinan itu'],
  B=['persoalan itu baru dibicarakan di antara keluarga dan belum melibatkan tokoh setempat', 'sejauh ini penyelesaian dilakukan sebatas keluarga dan belum ada tokoh yang dilibatkan'],
  beda_pada='peristiwa', beda_maksud='versi A: tokoh setempat sudah diminta menengahi; versi B: baru di antara keluarga - berselisih pada PERISTIWA/pelaku penengah')

# ------------------------------------------------------------------ calon mempelai menghadap (urutan 161)
